-- Test 1: bilingual 4-option MCQ bank (14 UAE trades × 10 questions).
-- Correct option stays server-side; workers submit the option id.

ALTER TABLE public.worker_skill_quiz_items
  ADD COLUMN IF NOT EXISTS correct_option text;

ALTER TABLE public.worker_skill_quiz_responses
  ADD COLUMN IF NOT EXISTS selected_option text;

COMMENT ON COLUMN public.worker_skill_quiz_items.correct_option IS
  'MCQ answer key (option id). Never returned by get_worker_quiz_items.';
COMMENT ON COLUMN public.worker_skill_quiz_responses.selected_option IS
  'Worker-selected option id for 4-choice questions. Boolean Yes/No stays in answer.';

CREATE OR REPLACE FUNCTION public.grade_worker_quiz_response()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_expected boolean;
  v_correct_option text;
BEGIN
  SELECT expected_answer, correct_option
    INTO v_expected, v_correct_option
  FROM public.worker_skill_quiz_items
  WHERE id = NEW.quiz_item_id;

  IF v_correct_option IS NOT NULL AND length(trim(v_correct_option)) > 0 THEN
    NEW.is_correct := (
      NEW.selected_option IS NOT NULL
      AND NEW.selected_option = v_correct_option
    );
  ELSIF v_expected IS NULL THEN
    NEW.is_correct := false;
  ELSE
    NEW.is_correct := (NEW.answer IS NOT NULL AND NEW.answer = v_expected);
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_grade_worker_quiz_response ON public.worker_skill_quiz_responses;
CREATE TRIGGER trg_grade_worker_quiz_response
BEFORE INSERT OR UPDATE ON public.worker_skill_quiz_responses
FOR EACH ROW EXECUTE FUNCTION public.grade_worker_quiz_response();

CREATE OR REPLACE FUNCTION public.submit_worker_quiz(p_answers jsonb, p_user_id uuid DEFAULT NULL)
RETURNS TABLE (score numeric, correct_count integer, total_count integer)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_subject uuid;
  v_total integer := 0;
  v_correct integer := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF p_answers IS NULL OR jsonb_typeof(p_answers) <> 'array' THEN
    RAISE EXCEPTION 'Invalid answers payload';
  END IF;

  v_subject := COALESCE(p_user_id, v_uid);
  IF v_subject IS DISTINCT FROM v_uid AND NOT public.partner_manages_worker(v_subject) THEN
    RAISE EXCEPTION 'Not allowed to submit a quiz for this worker';
  END IF;

  INSERT INTO public.worker_skill_quiz_responses (user_id, quiz_item_id, answer, selected_option, is_correct)
  SELECT v_subject,
         (a->>'quiz_item_id')::uuid,
         CASE
           WHEN jsonb_typeof(a->'answer') = 'boolean' THEN (a->>'answer')::boolean
           WHEN lower(COALESCE(a->>'answer', '')) IN ('true', 'false') THEN (a->>'answer')::boolean
           ELSE false
         END,
         CASE
           WHEN jsonb_typeof(a->'answer') = 'boolean' THEN NULL
           WHEN lower(COALESCE(a->>'answer', '')) IN ('true', 'false') THEN NULL
           ELSE NULLIF(trim(a->>'answer'), '')
         END,
         false
  FROM jsonb_array_elements(p_answers) a
  WHERE (a->>'quiz_item_id') IS NOT NULL
  ON CONFLICT (user_id, quiz_item_id) DO UPDATE
    SET answer = EXCLUDED.answer,
        selected_option = EXCLUDED.selected_option;

  SELECT count(*)::int,
         count(*) FILTER (WHERE r.is_correct)::int
    INTO v_total, v_correct
  FROM public.worker_skill_quiz_responses r
  WHERE r.user_id = v_subject
    AND r.quiz_item_id IN (
      SELECT (a->>'quiz_item_id')::uuid FROM jsonb_array_elements(p_answers) a
      WHERE (a->>'quiz_item_id') IS NOT NULL
    );

  RETURN QUERY
  SELECT CASE WHEN v_total > 0
              THEN round((v_correct::numeric / v_total) * 1000) / 10
              ELSE 0 END,
         v_correct,
         v_total;
END;
$$;

REVOKE ALL ON FUNCTION public.submit_worker_quiz(jsonb, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.submit_worker_quiz(jsonb, uuid) TO authenticated;

-- Retire old Yes/No items for trades that now have a 10-question MCQ bank.
UPDATE public.worker_skill_quiz_items
SET active = false, updated_at = now()
WHERE skill_code IN (
    'Electrician', 'Plumber', 'Welder', 'Mason', 'Carpenter', 'Helper', 'HVAC Technician',
    'Shuttering Carpenter', 'Mason (tiles/marble)', 'Construction Labour/Helper',
    'Pipe Fitter', 'Furniture Carpenter - Finishing, All Rounder', 'Steel Fixer',
    'AC Technician', 'General Labour - Warehouse/Supermarket', 'Scaffolder',
    'Painter', 'Aluminium Fixer/Fabricator'
  )
  AND (options IS NULL OR jsonb_typeof(options) <> 'array' OR jsonb_array_length(options) < 2);

-- 10 questions, 60% pass (6/10) per UAE listed trade.
UPDATE public.skill_quiz_configs
SET questions_to_show = 10,
    pass_score = 60,
    selection_mode = 'random_active',
    active = true,
    updated_at = now()
WHERE region IS NULL
  AND skill_code IN (
    'Electrician', 'Welder', 'Plumber', 'Shuttering Carpenter',
    'Mason (tiles/marble)', 'Construction Labour/Helper', 'Pipe Fitter',
    'Furniture Carpenter - Finishing, All Rounder', 'Steel Fixer',
    'AC Technician', 'General Labour - Warehouse/Supermarket',
    'Scaffolder', 'Painter', 'Aluminium Fixer/Fabricator'
  );

INSERT INTO public.skill_quiz_configs
  (skill_code, region, questions_to_show, selection_mode, selected_ids, pass_score, active)
SELECT v.skill_code, NULL, 10, 'random_active', '{}'::uuid[], 60, true
FROM (VALUES
  ('Electrician'),
  ('Welder'),
  ('Plumber'),
  ('Shuttering Carpenter'),
  ('Mason (tiles/marble)'),
  ('Construction Labour/Helper'),
  ('Pipe Fitter'),
  ('Furniture Carpenter - Finishing, All Rounder'),
  ('Steel Fixer'),
  ('AC Technician'),
  ('General Labour - Warehouse/Supermarket'),
  ('Scaffolder'),
  ('Painter'),
  ('Aluminium Fixer/Fabricator')
) AS v(skill_code)
WHERE NOT EXISTS (
  SELECT 1
  FROM public.skill_quiz_configs c
  WHERE c.skill_code = v.skill_code
    AND c.region IS NULL
);


-- Bilingual MCQ seed (14 trades × 10).
DELETE FROM public.worker_skill_quiz_responses
WHERE quiz_item_id IN (
  SELECT id FROM public.worker_skill_quiz_items WHERE correct_option IS NOT NULL
);
DELETE FROM public.worker_skill_quiz_items WHERE correct_option IS NOT NULL;

